const EXPECTED_VERIFY_TOKEN = 'hyfo9876';
const q = $input.first().json.query || {};
const tokenOk = q['hub.verify_token'] === EXPECTED_VERIFY_TOKEN;
return [{ json: { challenge: q['hub.challenge'], tokenOk } }];

// Formato real do webhook da Meta Cloud API (nao Evolution API)
const body = $input.first().json.body || $input.first().json;
const value = body?.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];
const phone = msg?.from || '';
const text = msg?.text?.body || '';
const pushName = value?.contacts?.[0]?.profile?.name || '';
// eventos de status (sent/delivered/read) chegam no mesmo webhook e nao tem 'messages' -
// sem essa checagem, phone/text vazios derrubavam o Postgres Chat Memory (Key vazia)
return [{ json: { phone, text, pushName, isMessage: Boolean(msg) } }];
